document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("main-textarea"),e=document.getElementById("save-status");window.location.hostname;let o=null;t.addEventListener("input",()=>{e.textContent="編輯中...",e.style.color="#888",clearTimeout(o),o=setTimeout(()=>{!async function(){const o=t.value;e.textContent="儲存中...",e.style.color="#888";try{const t={message:o};(await fetch("http://192.168.3.85:9090/todo/saveMessage",{method:"POST",headers:{accept:"*/*","Content-Type":"application/json"},body:JSON.stringify(t)})).ok?(e.textContent="已自動儲存 ✓",e.style.color="#2ecc71",setTimeout(()=>{"已自動儲存 ✓"===e.textContent&&(e.textContent="")},3e3)):(e.textContent="儲存失敗 ✕",e.style.color="#e74c3c")}catch(t){console.error("發送訊息錯誤:",t),e.textContent="網路錯誤，儲存失敗 ✕",e.style.color="#e74c3c"}}()},1e3)}),async function(){try{e.textContent="載入中...";const o=await fetch("http://192.168.3.85:9090/todo/getMessage",{method:"GET",headers:{accept:"*/*"}});if(!o.ok)throw new Error("Network response was not ok");const n=await o.json();if(n&&n.length>0){const e=n[n.length-1].message||"";t.value=e}e.textContent="已載入最新內容",e.style.color="#888",setTimeout(()=>{"已載入最新內容"===e.textContent&&(e.textContent="")},2e3)}catch(t){console.error("無法取得交接事項:",t),e.textContent="載入失敗",e.style.color="#e74c3c"}}()});